/* STATIC (default) — normal flow, top/right/bottom/left have no effect */
.normal { position: static; }

/* RELATIVE — stays in flow, offset from its natural position */
.shifted {
  position: relative;
  top: 10px;   /* moves DOWN 10px from where it would normally be */
  left: 20px;
}

/* ABSOLUTE — removed from flow, placed relative to nearest positioned ancestor */
.tooltip {
  position: absolute;
  top: 0;
  right: 0;   /* top-right corner of containing block */
}

/* FIXED — removed from flow, placed relative to VIEWPORT — stays while scrolling */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
}

/* STICKY — in flow until threshold, then fixed */
.sticky-nav {
  position: sticky;
  top: 0;   /* sticks when it reaches 0px from top of viewport */
  z-index: 50;
}

/* Pattern: position: relative on parent, absolute on child */
.card {
  position: relative;    /* makes this the containing block */
}

.card .badge {
  position: absolute;
  top: 12px;
  right: 12px;           /* top-right corner of .card, not the page */
}

/* Without position: relative on .card,
   .badge would be positioned relative to the nearest
   positioned ancestor — possibly the entire page */

/* Higher z-index = closer to the viewer */
.modal-overlay  { position: fixed; z-index: 300; }
.modal          { position: fixed; z-index: 400; }
.tooltip        { position: absolute; z-index: 200; }
.header         { position: fixed; z-index: 100; }

/* z-index only works on POSITIONED elements (not static) */
.div-no-position { z-index: 999; }  /* has NO effect */
